def transform(grid):
    h, w = len(grid), len(grid[0])
    fours = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    sixes = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    out = [row[:] for row in grid]

    if not fours or not sixes:
        return out

    dr = sum(r for r, c in sixes) / len(sixes) - sum(r for r, c in fours) / len(fours)
    dc = sum(c for r, c in sixes) / len(sixes) - sum(c for r, c in fours) / len(fours)

    for r, c in sixes:
        out[r][c] = 0

    if abs(dr) >= abs(dc):
        edge = max(r for r, c in fours) if dr > 0 else min(r for r, c in fours)
        reflected = [(2 * edge + (1 if dr > 0 else -1) - r, c) for r, c in fours]
    else:
        edge = max(c for r, c in fours) if dc > 0 else min(c for r, c in fours)
        reflected = [(r, 2 * edge + (1 if dc > 0 else -1) - c) for r, c in fours]

    for r, c in reflected:
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = 4

    return out
